module tb;
    logic clk;
    logic [7:0] in;
    logic [7:0] anyedge;

    TopModule dut (
        .clk(clk),
        .in(in),
        .anyedge(anyedge)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        in = 8'h00;
        @(posedge clk);
        #1;
        // Check initial state
        if (anyedge !== 8'h00) begin
            $display("SELFFAIL: Initial anyedge is not 0 (got %h)", anyedge);
            $finish;
        end

        // Change in to 8'h01 at negative edge (or well before posedge)
        @(negedge clk);
        in = 8'h01; // Transition happens here

        @(posedge clk);
        #1;
        // Next cycle after transition, anyedge should be 8'h01
        if (anyedge !== 8'h01) begin
            $display("SELFTEST FAIL: expected anyedge=01 after transition, got %h", anyedge);
            $finish;
        end

        // Next cycle with no change, anyedge should go back to 0
        @(posedge clk);
        #1;
        if (anyedge !== 8'h00) begin
            $display("SELFTEST FAIL: expected anyedge=00 when no change, got %h", anyedge);
            $finish;
        end

        // Change multiple bits
        @(negedge clk);
        in = 8'hF0;

        @(posedge clk);
        #1;
        // Transition from 01 to F0 -> bits 0, 4, 5, 6, 7 changed.
        // in was 01 (00000001), now F0 (11110000). XOR = 11110001 = F1.
        if (anyedge !== 8'hF1) begin
            $display("SELFTEST FAIL: expected anyedge=F1, got %h", anyedge);
            $finish;
        end

        @(posedge clk);
        #1;
        if (anyedge !== 8'h00) begin
            $display("SELFTEST FAIL: expected anyedge=00, got %h", anyedge);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module TopModule (
    input logic clk,
    input logic [7:0] in,
    output logic [7:0] anyedge
);
    logic [7:0] in_q = '0;

    always_ff @(posedge clk) begin
        in_q <= in;
        anyedge <= in ^ in_q;
    end

endmodule

module tb;
    logic clk;
    logic [7:0] in;
    logic [7:0] anyedge;

    TopModule dut (
        .clk(clk),
        .in(in),
        .anyedge(anyedge)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        in = 8'h00;
        @(posedge clk);
        #1;
        if (anyedge !== 8'h00) begin
            $display("SELFTEST FAIL: Initial anyedge is not 0 (got %h)", anyedge);
            $finish;
        end

        // 0 to 1 transition
        @(negedge clk);
        in = 8'hFF;

        @(posedge clk);
        #1;
        if (anyedge !== 8'hFF) begin
            $display("SELFTEST FAIL: 0->FF edge failed, got %h", anyedge);
            $finish;
        end

        // No change
        @(posedge clk);
        #1;
        if (anyedge !== 8'h00) begin
            $display("SELFTEST FAIL: no change should give 0, got %h", anyedge);
            $finish;
        end

        // 1 to 0 transition (falling edge)
        @(negedge clk);
        in = 8'h0F;

        @(posedge clk);
        #1;
        // FF -> 0F means upper 4 bits changed from 1 to 0. XOR is F0.
        if (anyedge !== 8'hF0) begin
            $display("SELFTEST FAIL: FF->0F edge failed, got %h", anyedge);
            $finish;
        end

        @(posedge clk);
        #1;
        if (anyedge !== 8'h00) begin
            $display("SELFTEST FAIL: no change should give 0, got %h", anyedge);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
